@extends('layout') @section('content')<section><span class="eyebrow">ADMINISTRACIÓN DEL ALBERGUE</span><h1>{{ $def[1] }}</h1>@include('admin-nav')<div class="admin-grid"><article class="card"><h2>{{ $editing?'Editar registro':'Nuevo registro' }}</h2><form method="post" action="/admin/{{ $kind }}{{ $editing?'/'.$editing->id:'' }}">@csrf @if($editing) @method('PUT') @endif @foreach($def[2] as $field=>$label)<label>{{ $label }}@php $rule=$def[3][$field]; $choices=null;foreach(explode('|',$rule) as $part){if(str_starts_with($part,'in:'))$choices=explode(',',substr($part,3));} if($field==='is_published')$choices=['0','1']; @endphp @if($choices)<select name="{{ $field }}">@foreach($choices as $choice)<option value="{{ $choice }}" @selected((string)old($field,$editing?->$field)===(string)$choice)>{{ $field==='is_published'?($choice==='1'?'Visible':'Oculta'):$choice }}</option>@endforeach</select>@elseif($field==='description')<textarea name="{{ $field }}">{{ old($field,$editing?->$field) }}</textarea>@else<input name="{{ $field }}" value="{{ old($field,$editing?->$field) }}" @if(in_array($field,['quantity','amount','need_id'])) type="number" step="{{ $field==='amount'?'0.01':'1' }}" @endif>@endif</label>@endforeach<button>Guardar registro</button>@if($editing)<a href="/admin/{{ $kind }}">Cancelar</a>@endif</form></article><article class="card"><h2>Registros <span class="badge">{{ $items->total() }}</span></h2>@forelse($items as $item)<div class="record"><h3>{{ $item->name ?? $item->title ?? 'Aporte #'.$item->id }}</h3><p>{{ $item->description }}</p><span class="badge">{{ $item->status ?? $item->adoption_status }}</span><div class="actions"><a href="/admin/{{ $kind }}/{{ $item->id }}/editar">Editar</a><form method="post" action="/admin/{{ $kind }}/{{ $item->id }}" data-confirm="¿Eliminar este registro?">@csrf @method('DELETE')<button class="danger">Eliminar</button></form></div></div>@empty<p>No hay registros todavía.</p>@endforelse{{ $items->links() }}</article></div></section>@endsection